import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"プライバシーポリシー","description":"Palleria における個人情報および利用データの取り扱い方針","frontmatter":{"title":"プライバシーポリシー","description":"Palleria における個人情報および利用データの取り扱い方針"},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md","lastUpdated":1789107345000}'),i={name:"privacy-policy.md"};function o(n,t,s,d,h,c){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>最終更新日: 2026年8月11日</p><p><strong>Palleria</strong>（以下「本アプリ」）は、ユーザーのプライバシーを最優先事項として設計されています。本ポリシーでは、本アプリがどのようなデータを収集・保持し、どのように保護しているかを説明します。</p><hr><h2 id="_1-基本方針" tabindex="-1">1. 基本方針 <a class="header-anchor" href="#_1-基本方針" aria-label="Permalink to &quot;1. 基本方針&quot;">​</a></h2><p>本アプリは、非公式の Pixiv クライアントアプリケーションです。ユーザーの Pixiv アカウント情報やアクティビティデータが、開発者や第三者の未承認サーバーへ送信・売却されることは一切ありません。</p><hr><h2 id="_2-取り扱うデータと保存場所" tabindex="-1">2. 取り扱うデータと保存場所 <a class="header-anchor" href="#_2-取り扱うデータと保存場所" aria-label="Permalink to &quot;2. 取り扱うデータと保存場所&quot;">​</a></h2><p>本アプリが取り扱う主要なデータとその管理方法は以下の通りです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">データ項目</th><th style="text-align:left;">保存場所</th><th style="text-align:left;">保護・処理方法</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pixiv 認証トークン</strong></td><td style="text-align:left;">端末ローカル (KeyStore)</td><td style="text-align:left;">Android KeyStore を通じた <strong>AES-256-GCM 暗号化保存</strong>。Pixiv 公式認証サーバーとの通信にのみ使用されます。</td></tr><tr><td style="text-align:left;"><strong>閲覧履歴・検索履歴</strong></td><td style="text-align:left;">端末ローカル (Room DB)</td><td style="text-align:left;">端末内にのみ暗号化/保存されます。設定画面からいつでも一括消去・自動消去が可能です。</td></tr><tr><td style="text-align:left;"><strong>アプリ設定・ウォッチリスト</strong></td><td style="text-align:left;">端末ローカル (DataStore)</td><td style="text-align:left;">端末内に保存され、外部へ自動送信されません。</td></tr><tr><td style="text-align:left;"><strong>ダウンロード画像データ</strong></td><td style="text-align:left;">端末ストレージ</td><td style="text-align:left;">ユーザーが指定したストレージディレクトリに保存されます。</td></tr></tbody></table><hr><h2 id="_3-テレメトリおよびクラッシュレポート" tabindex="-1">3. テレメトリおよびクラッシュレポート <a class="header-anchor" href="#_3-テレメトリおよびクラッシュレポート" aria-label="Permalink to &quot;3. テレメトリおよびクラッシュレポート&quot;">​</a></h2><p>本アプリは、アプリのクラッシュ解析およびパフォーマンス計測のために GlitchTip（Sentry Android SDK 互換）を使用しています。</p><ul><li><strong>オプトイン設計</strong>: テレメトリ収集は<strong>デフォルトで完全無効</strong> (<code>sendTelemetry = false</code>) です。ユーザーが設定画面から明確に同意（有効化）しない限り、ログデータの自動送信は一切行われません。</li><li><strong>収集されるデータ</strong>: 未捕獲の例外スタックトレース、OS バージョン、端末モデル、アプリの起動・画面表示に関するパフォーマンス情報（1% サンプリング）。</li><li><strong>非収集データ</strong>: Pixiv トークン、パスワード、検索キーワード、閲覧履歴、ダウンロード画像などの個人識別情報は<strong>一切含まれません</strong>。</li></ul><hr><h2 id="_4-pallasync-データ同期機能" tabindex="-1">4. PallaSync データ同期機能 <a class="header-anchor" href="#_4-pallasync-データ同期機能" aria-label="Permalink to &quot;4. PallaSync データ同期機能&quot;">​</a></h2><p>ユーザーが「PallaSync」同期機能を有効化した場合、設定データおよびウォッチリストが同期サーバーへ送信されます。</p><ul><li>送信されるデータは端末上で <strong>AES-256-GCM 方式により暗号化</strong> された状態で送信・保存されます。</li><li>暗号化キーはユーザーの KeyStore 内で保持されるため、サーバー側で平文データが復号・閲覧されることはありません。</li></ul><hr><h2 id="_5-アプリセキュリティ-画面保護" tabindex="-1">5. アプリセキュリティ &amp; 画面保護 <a class="header-anchor" href="#_5-アプリセキュリティ-画面保護" aria-label="Permalink to &quot;5. アプリセキュリティ &amp; 画面保護&quot;">​</a></h2><ul><li><strong>アプリロック</strong>: PIN コードおよび生体認証（指紋/顔認証）による起動制限をサポート。</li><li><strong>画面保護 (<code>FLAG_SECURE</code>)</strong>: スクリーンショット撮影、画面録画、タスク切替画面でのプレビュー表示の遮断機能を備えています。</li></ul><hr><h2 id="_6-プライバシーポリシーの変更" tabindex="-1">6. プライバシーポリシーの変更 <a class="header-anchor" href="#_6-プライバシーポリシーの変更" aria-label="Permalink to &quot;6. プライバシーポリシーの変更&quot;">​</a></h2><p>本アプリの機能追加や法改正に伴い、本プライバシーポリシーを改定することがあります。変更が生じた場合は、本ドキュメントおよび GitHub リポジトリにて周知いたします。</p><hr><h2 id="_7-お問い合わせ" tabindex="-1">7. お問い合わせ <a class="header-anchor" href="#_7-お問い合わせ" aria-label="Permalink to &quot;7. お問い合わせ&quot;">​</a></h2><p>本プライバシーポリシーに関するご質問やご意見は、<a href="https://github.com/yunfie-twitter/Palleria/issues" target="_blank" rel="noreferrer">GitHub Issues</a> よりお問い合わせください。</p>',27)])])}const _=e(i,[["render",o]]);export{p as __pageData,_ as default};
